import sys,json
def emit(o):
  sys.stdout.write(json.dumps(o)+'\n'); sys.stdout.flush()
for line in sys.stdin:
  m=json.loads(line)
  method=m.get('method')
  if method=='initialize':
    emit({'jsonrpc':'2.0','id':m.get('id'),'result':{'protocolVersion':'2025-11-25','capabilities':{},'serverInfo':{'name':'example-readonly','version':'1.0.0'}}})
  elif method=='notifications/initialized':
    pass
  elif method=='tools/list':
    emit({'jsonrpc':'2.0','id':m.get('id'),'result':{'tools':[{'name':'read_item','description':'Read one read-only item (never writes)','inputSchema':{'type':'object','properties':{'id':{'type':'string'}}}}]}})
  elif method=='tools/call':
    args=m.get('params',{}).get('arguments',{})
    if m.get('params',{}).get('name')=='read_item':
      emit({'jsonrpc':'2.0','id':m.get('id'),'result':{'content':[{'type':'text','text':json.dumps({'id':args.get('id'),'value':'readonly-value'})}],'isError':False}})
    else:
      emit({'jsonrpc':'2.0','id':m.get('id'),'error':{'code':-32601,'message':'unknown tool'}})
  else:
    emit({'jsonrpc':'2.0','id':m.get('id'),'error':{'code':-32601,'message':'method not found'}})
